from itertools import product

sums = [d1 + d2 for d1, d2 in product(range(1, 7), repeat=2)]
pmf = {s: sums.count(s) / 36 for s in range(2, 13)}
print(round(sum(pmf.values()), 12))                 # PMF sums to 1
cdf = 0.0
for s in sorted(pmf):
    cdf += pmf[s]
    if s in (7, 10):
        print(s, round(cdf, 4))                     # F(7), F(10)
print(round(sum(pmf[s] for s in range(8, 11)), 4))  # P(8 <= X <= 10)
